# ---------------- COMMON JS ----------------
common_js = r"""
const CAR_IMG={r:"data:image/png;base64,",l:"data:image/png;base64,"};
function carIcon(left){return {url:left?CAR_IMG.l:CAR_IMG.r,scaledSize:new google.maps.Size(70,38),anchor:new google.maps.Point(35,26)};}
function clampSec(v,lo,hi){return Math.max(lo,Math.min(hi,v));}
function hav(a,b){const t=Math.PI/180,dLat=(b.lat-a.lat)*t,dLng=(b.lng-a.lng)*t;
 const x=Math.sin(dLat/2)**2+Math.cos(a.lat*t)*Math.cos(b.lat*t)*Math.sin(dLng/2)**2;return 2*6371000*Math.asin(Math.sqrt(x));}
function bearingDeg(a,b){const t=Math.PI/180,y=Math.sin((b.lng-a.lng)*t)*Math.cos(b.lat*t);
 const x=Math.cos(a.lat*t)*Math.sin(b.lat*t)-Math.sin(a.lat*t)*Math.cos(b.lat*t)*Math.cos((b.lng-a.lng)*t);
 return (Math.atan2(y,x)/t+360)%360;}
async function pathBetween(a,b){
 try{
  if(!RouteClass)throw new Error("no routes lib");
  const r=await RouteClass.computeRoutes({origin:a,destination:b,travelMode:"DRIVING",fields:["path","distanceMeters","durationMillis"]});
  if(!r.routes||!r.routes.length)throw new Error("no route");
  const rt=r.routes[0];
  return {coords:rt.path.map(p=>({lat:p.lat,lng:p.lng})),km:rt.distanceMeters/1000};
 }catch(e){console.error(e);return {coords:[a,b],km:hav(a,b)*1.3/1000};}
}
/* Smooth constant-speed movement (requestAnimationFrame) with gentle start/stop; car image flips left/right by direction */
function animateAlong(o){
 const marker=o.marker,dur=o.durationMs,color=o.color||"#22c55e";
 const P=[o.coords[0]];for(let i=1;i<o.coords.length;i++){if(hav(P[P.length-1],o.coords[i])>0.5)P.push(o.coords[i]);}
 if(P.length<2){marker.setPosition(P[0]);if(o.onProgress)o.onProgress(1);if(o.onDone)o.onDone();return {cancel(){}};}
 const cum=[0];for(let i=1;i<P.length;i++)cum.push(cum[i-1]+hav(P[i-1],P[i]));
 const total=cum[cum.length-1];
 function at(d){d=Math.max(0,Math.min(total,d));let lo=0,hi=cum.length-1;
  while(hi-lo>1){const m=(lo+hi)>>1;if(cum[m]<=d)lo=m;else hi=m;}
  const seg=(cum[hi]-cum[lo])||1,f=(d-cum[lo])/seg;
  return {lat:P[lo].lat+(P[hi].lat-P[lo].lat)*f,lng:P[lo].lng+(P[hi].lng-P[lo].lng)*f};}
 const A=0.08,V=1/(1-A);
 function prog(t){if(t<=0)return 0;if(t>=1)return 1;if(t<A)return V*t*t/(2*A);if(t>1-A)return 1-V*(1-t)*(1-t)/(2*A);return V*(t-A/2);}
 let faceLeft=Math.sin(bearingDeg(P[0],at(30))*Math.PI/180)<0,cancelled=false;
 marker.setPosition(P[0]);marker.setIcon(carIcon(faceLeft));
 const start=performance.now();
 function frame(now){
  if(cancelled)return;
  const t=Math.min(1,(now-start)/dur),d=prog(t)*total,pos=at(d),ahead=at(d+30);
  marker.setPosition(pos);
  if(hav(pos,ahead)>2){const sn=Math.sin(bearingDeg(pos,ahead)*Math.PI/180);if(sn>0.3&&faceLeft){faceLeft=false;marker.setIcon(carIcon(false));}else if(sn<-0.3&&!faceLeft){faceLeft=true;marker.setIcon(carIcon(true));}}
  if(o.onProgress)o.onProgress(t);
  if(t<1)requestAnimationFrame(frame);else if(o.onDone)o.onDone();
 }
 requestAnimationFrame(frame);
 return {cancel(){cancelled=true;}};
}
"""


