@app.route("/drivers", methods=["POST"])
def generate_drivers():
    data=request.get_json(force=True)
    lat=float(data["lat"]);lon=float(data["lon"])
    selected=random.sample(DRIVER_POOL, random.randint(10,12))
    generated=[]
    for i,profile in enumerate(selected):
        x=random.uniform(-8,8);y=random.uniform(-8,8)
        dist=math.hypot(x,y);angle=math.degrees(math.atan2(y,x))
        dlat=y/111.0
        cos_lat=max(0.01,abs(math.cos(math.radians(lat))))
        dlon=x/(111.0*cos_lat)*(1 if lat>=0 else -1)
        generated.append({**profile,"id":f"Driver {i+1:02d}","x":x,"y":y,"distance":dist,"angle":angle,
                          "nearby":dist<=5,"lat":lat+dlat,"lon":lon+dlon})
    with state_lock:
        driver_store.clear()
        for i, d in enumerate(generated, start=1):
            d["id"] = i
            d["online"] = True
            d["lat"] = lat + (d["y"] / 111.0)
            d["lon"] = lon + (d["x"] / (111.0 * max(0.01, abs(math.cos(math.radians(lat))))))
            driver_store[i] = d
    return jsonify(generated)

@app.route("/api/drivers")
def api_drivers():
    with state_lock:
        return jsonify([{k:d[k] for k in ("id","name","car","plate","rating","online","distance")} for d in driver_store.values()])

def run_automatic_matching(ride_id):
    """Simulate driver responses: every driver gets a 10-second window, once only."""
    with state_lock:
        ride=ride_store.get(ride_id)
        if not ride:
            return
        candidates=sorted(
            [d for d in driver_store.values() if d.get("online") and d.get("distance",999)<=5],
            key=lambda d:d["distance"]
        )
        ride["total_candidates"]=len(candidates)
        ride["contacted_drivers"]=[]
    approach_secs=20
    for index, driver in enumerate(candidates, start=1):
        with state_lock:
            ride=ride_store.get(ride_id)
            if not ride or ride["status"]=="cancelled":
                return
            ride["status"]="contacting_driver"
            ride["driver_id"]=driver["id"]
            ride["attempt_number"]=index
            ride["response_deadline"]=time.time()+10
            ride["contacted_drivers"].append(driver["id"])
            ride["contacted_count"]=len(ride["contacted_drivers"])
        # Simulated driver behavior: some accept, some reject, and some time out.
        # The driver gets the full 10-second response window; response occurs within it.
        outcome=random.choices(["accept","reject","timeout"],weights=[0.65,0.20,0.15],k=1)[0]
        if outcome=="timeout":
            time.sleep(10)
        else:
            time.sleep(random.uniform(2.0,9.0))
        with state_lock:
            ride=ride_store.get(ride_id)
            if not ride or ride["status"]=="cancelled":
                return
            if ride["driver_id"]!=driver["id"] or ride["status"]!="contacting_driver":
                return
            if outcome=="accept":
                ride["status"]="arriving"
                ride["assigned_at"]=time.time()
                approach_secs=round(clamp(driver.get("distance",1)*1.3*10,15,40))
                ride["approach_seconds"]=approach_secs
                ride["response_deadline"]=None
                ride["driver_lat"]=driver["lat"]
                ride["driver_lon"]=driver["lon"]
                ride["otp_verified"]=False
                break
            ride["last_driver_result"]="timed_out" if outcome=="timeout" else "rejected"
            ride["response_deadline"]=None
    else:
        with state_lock:
            ride=ride_store.get(ride_id)
            if ride and ride["status"]!="cancelled":
                ride["status"]="no_driver"
                ride["driver_id"]=None
                ride["response_deadline"]=None
        return

    # Simulated driver reaches pickup; OTP is generated and auto-verified in this
    # driverless demo because the user explicitly requested no manual driver UI.
    time.sleep(approach_secs+3)
    with state_lock:
        ride=ride_store.get(ride_id)
        if not ride or ride["status"]!="arriving":
            return
        ride["otp_verified"]=True
        ride["status"]="in_trip"
        ride["trip_started_at"]=time.time()
        trip_secs=ride.get("trip_seconds",30)

    # Trip lasts as long as the passenger map animation (+ small buffer).
    time.sleep(trip_secs+3)
    with state_lock:
        ride=ride_store.get(ride_id)
        if ride and ride["status"]=="in_trip":
            ride["status"]="completed"
            ride["completed_at"]=time.time()

@app.route("/api/ride/request", methods=["POST"])
def create_ride():
    global ride_counter
    data=request.get_json(force=True)
    with state_lock:
        eligible=[d for d in driver_store.values() if d.get("online") and d.get("distance",999)<=5]
        if not eligible:
            return jsonify(message="No simulated drivers within 5 km. Confirm pickup to generate nearby drivers."),409
        ride_counter+=1
        ride={
            "id":ride_counter,
            "pickup_lat":data["pickup"]["lat"],"pickup_lon":data["pickup"]["lon"],
            "destination_lat":data["destination"]["lat"],"destination_lon":data["destination"]["lon"],
            "distance_km":data["distance_km"],"total_fare":data["total_fare"],
            "status":"searching","driver_id":None,"otp":f"{random.randint(0,9999):04d}",
            "created_at":time.time(),"contacted_drivers":[],"response_deadline":None,
            "attempt_number":0,"contacted_count":0,"total_candidates":len(eligible),
            "otp_verified":False,
            "trip_seconds":round(clamp(float(data["distance_km"])*8,25,60)),
            "category":data.get("category","general"),
            "approach_seconds":20
        }
        ride_store[ride_counter]=ride
        new_ride_id=ride_counter
    threading.Thread(target=run_automatic_matching,args=(new_ride_id,),daemon=True).start()
    return jsonify(message="Automatic driver matching started.",ride_id=new_ride_id)

@app.route("/api/ride/<int:rid>/cancel",methods=["POST"])
def cancel_ride(rid):
    with state_lock:
        if rid not in ride_store:return jsonify(message="Ride not found."),404
        ride_store[rid]["status"]="cancelled"
    return jsonify(message="Ride cancelled.")

@app.route("/api/ride/<int:rid>/passenger")
def passenger_ride(rid):
    with state_lock:
        r=ride_store.get(rid)
        if not r:return jsonify(message="Ride not found."),404
        safe={k:v for k,v in r.items() if k not in ("contacted_drivers",)}
        did=r.get("driver_id")
        driver=driver_store.get(did,{}) if did is not None else {}
        safe["driver"]={k:driver.get(k) for k in ("name","car","plate","rating","lat","lon")} if driver else None
    return jsonify(safe)


# ---------------- DRIVER MODE (simulated passenger requests) ----------------
PASSENGERS = [("Sana","4.9"),("Ayesha","4.8"),("Fatima","4.7"),("Hira","4.9"),("Kamran","4.8"),("Nida","4.6"),
              ("Rizwan","4.9"),("Mehwish","4.7"),("Talha","4.8"),("Areeba","4.9"),("Owais","4.7"),("Maryam","4.8")]

def km_offset(lat, lon, x_km, y_km):
    return lat + y_km/111.0, lon + x_km/(111.0*max(0.01, abs(math.cos(math.radians(lat)))))

def haversine_km(la1, lo1, la2, lo2):
    p=math.pi/180
    a=math.sin((la2-la1)*p/2)**2+math.cos(la1*p)*math.cos(la2*p)*math.sin((lo2-lo1)*p/2)**2
    return 2*6371*math.asin(math.sqrt(a))

def spawn_driver_request(lat, lon):
    global driver_req_counter
    driver_req_counter+=1
    r=random.uniform(0.4,4.8);a=random.uniform(0,2*math.pi)
    plat,plon=km_offset(lat,lon,r*math.cos(a),r*math.sin(a))
    trip=random.uniform(2.0,10.0);b=random.uniform(0,2*math.pi)
    dlat,dlon=km_offset(plat,plon,trip*math.cos(b),trip*math.sin(b))
    road=round(trip*1.3,2)
    name,rating=random.choice(PASSENGERS)
    driver_requests[driver_req_counter]={
        "id":driver_req_counter,"name":name,"rating":rating,
        "pickup_lat":plat,"pickup_lon":plon,"destination_lat":dlat,"destination_lon":dlon,
        "trip_km":road,"fare":round(150+50*road),"otp":f"{random.randint(0,9999):04d}",
        "expires_at":time.time()+random.uniform(25,35)
    }

