@app.route("/api/driver/requests", methods=["POST"])
def driver_feed():
    data=request.get_json(force=True)
    lat=float(data["lat"]);lon=float(data["lon"])
    now=time.time()
    with state_lock:
        for k in [k for k,v in driver_requests.items() if now>v["expires_at"]]:
            del driver_requests[k]
        visible=[v for v in driver_requests.values() if haversine_km(lat,lon,v["pickup_lat"],v["pickup_lon"])<=5]
        if not visible:
            for _ in range(random.randint(1,2)):
                spawn_driver_request(lat,lon)
        elif len(visible)<4 and random.random()<0.3:
            spawn_driver_request(lat,lon)
        out=[]
        for v in driver_requests.values():
            d=haversine_km(lat,lon,v["pickup_lat"],v["pickup_lon"])
            if d<=5:
                item={k:val for k,val in v.items() if k not in ("otp","expires_at")}
                item["pickup_distance_km"]=d
                item["seconds_left"]=max(0,v["expires_at"]-now)
                out.append(item)
    out.sort(key=lambda x:x["pickup_distance_km"])
    return jsonify(out)

@app.route("/api/driver/request/<int:rid>/accept", methods=["POST"])
def driver_accept(rid):
    with state_lock:
        v=driver_requests.pop(rid,None)
        if not v or time.time()>v["expires_at"]:
            return jsonify(message="Request expired."),410
        driver_requests.clear()
    return jsonify(v)

@app.route("/api/driver/request/<int:rid>/reject", methods=["POST"])
def driver_reject(rid):
    with state_lock:
        driver_requests.pop(rid,None)
    return jsonify(status="ok")

